        const out = write ('tb-ptibound', "    parseToInt (n: any): number { return n; }\n    m (n: any) {\n        let s = '1';\n        const decimalsCount = this.parseToInt (n);\n        for (let i = 0; i < decimalsCount; i++) {\n            s = s + '0';\n        }\n        return this.hold (s);\n    }\n");
